// toSignal: convert Observable to signal for template use
@Component({
  template: `
    @if (user()) { <p>{{ user()!.name }}</p> }
  `
})
export class ProfileComponent {
  private userService = inject(UserService);
  // toSignal subscribes for you; initialValue shown until first emission
  user = toSignal(this.userService.currentUser$, { initialValue: null });
}

// toObservable: convert signal to Observable to use RxJS operators
@Injectable({ providedIn: 'root' })
export class SearchService {
  term = signal('');
  results$ = toObservable(this.term).pipe(
    debounceTime(300),
    distinctUntilChanged(),
    switchMap(t => this.http.get<Result[]>(\`/api/search?q=\${t}\`))
  );
}

// httpResource: reactive HTTP — auto-refetches when userId changes
@Component({
  template: `
    @if (userRes.isLoading()) { <spinner /> }
    @else if (userRes.error()) { <p>Error</p> }
    @else { <user-card [user]="userRes.value()!" /> }
  `
})
export class UserDetailComponent {
  userId = input.required<string>();
  userRes = httpResource<User>(() => \`/api/users/\${this.userId()}\`);
  // ↑ re-fetches automatically whenever userId() changes
}

// model(): two-way signal binding between parent and child
@Component({ selector: 'app-toggle', template: `<button (click)="checked.set(!checked())">...</button>` })
export class ToggleComponent {
  checked = model(false);  // writable; parent binds with [(checked)]="mySignal"
}

// effect with cleanup and untracked
effect((onCleanup) => {
  const id = setInterval(() => {
    const count = untracked(() => this.count());  // read without tracking
    console.log('tick:', count);
  }, 1000);
  onCleanup(() => clearInterval(id));  // cleanup when effect re-runs or destroyed
});
